const http = require("https");

const options = {
  "method": "POST",
  "hostname": "api.rootly.com",
  "port": null,
  "path": "/v1/incidents/%7Bincident_id%7D/alerts",
  "headers": {
    "content-type": "application/vnd.api+json",
    "Authorization": "Bearer REPLACE_BEARER_TOKEN"
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.write("{\"data\":{\"type\":\"alerts\",\"attributes\":{\"source\":\"string\",\"summary\":\"string\",\"service_ids\":[\"string\"],\"environment_ids\":[\"string\"],\"started_at\":\"2019-08-24T14:15:22Z\",\"ended_at\":\"2019-08-24T14:15:22Z\",\"labels\":[{\"key\":\"string\",\"value\":\"string\"}],\"data\":{}}}}");
req.end();

